"""Original lesson-4 content. Extends the existing learningV2 pilot, locally only.

Retains all historical questions and the original twenty formative task objects.
Never generates SQL, changes a published manifest or connects to any service.
"""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LANGS = ('ru', 'uk', 'en', 'sv')
def T(r, u, e, s): return dict(zip(LANGS, (r,u,e,s)))
def S(s): return T(s,s,s,s)
def E(s,r,u,e): return dict(sv=s,meaning=T(r,u,e,s))
def L(s,r,u,e,**kw): return dict(sv=s,ru=r,uk=u,en=e,**kw)
def W(s,r,u,e,ss=None): return dict(sv=s,meaning=T(r,u,e,ss or s))

lessons=json.loads((ROOT/'lessons.json').read_text())
lesson=next(l for l in lessons if l['id']=='lesson-4')
v=lesson['learningV2']
report=ROOT/'reports/presens';report.mkdir(parents=True,exist_ok=True)
baseline=report/'pilot-integrity.json'
def sha(x): return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
pilot=[q for q in v['questions'] if q['id'].startswith('presens-a-v2-q')]
assert len(pilot)==20
if not baseline.exists():
 baseline.write_text(json.dumps(dict(legacyQuestions=sha(lesson['questions']),pilotQuestions=sha(pilot),pilotWritingIds=[w['id'] for w in v['writing'][:2]],moduleId=v['id']),indent=2)+'\n')
v.update(revision=2,chapterVersion=1,pilotRuleIds=['now','forms','group1','group23','special','negation','questions','forms','future'])
v['description']=T('Расскажи о своём дне: формы глаголов, вопросы, отрицание и планы.','Розкажи про свій день: форми дієслів, запитання, заперечення й плани.','Talk about your day: verb forms, questions, negation and plans.','Berätta om din dag: verbformer, frågor, negation och planer.')
v['goals']=[T('Рассказать о привычках, занятиях сейчас и планах на завтра.','Розповісти про звички, заняття зараз і плани на завтра.','Describe habits, current activities and tomorrow’s plans.','Berätta om vanor, det du gör nu och morgondagens planer.'),T('Выбирать presens и инфинитив, в том числе после модальных глаголов.','Вибирати presens та інфінітив, зокрема після модальних дієслів.','Choose present and infinitive forms, including after modal verbs.','Välja presens och infinitiv, även efter hjälpverb.'),T('Строить утверждения, отрицания и два типа вопросов.','Будувати твердження, заперечення та два типи запитань.','Build statements, negatives and two kinds of question.','Bygga påståenden, nekande meningar och två typer av frågor.'),T('Понимать короткий разговор и написать собственный связный текст.','Розуміти коротку розмову й написати власний зв’язний текст.','Understand a short conversation and write your own connected text.','Förstå ett kort samtal och skriva en egen sammanhängande text.')]
v['sections']=[dict(id=i,title=t,rules=[]) for i,t in [
 ('meaning',T('1. Что выражает presens','1. Що виражає presens','1. What presens expresses','1. Vad presens uttrycker')),
 ('forms',T('2. Формы и четыре группы','2. Форми й чотири групи','2. Forms and four groups','2. Former och fyra grupper')),
 ('special',T('3. Особые и модальные глаголы','3. Особливі й модальні дієслова','3. Special verbs and modal verbs','3. Särskilda verb och hjälpverb')),
 ('sentences',T('4. Собираем предложения','4. Будуємо речення','4. Building sentences','4. Bygg meningar')),
 ('reference',T('5. Ошибки и шпаргалка','5. Помилки й шпаргалка','5. Errors and quick reference','5. Fel och snabbguide'))]]

def R(section,id,title,text,theory,pattern,examples,comparison,mistakes,limits,mini,answer,explanation,sources=None):
 next(s for s in v['sections'] if s['id']==section)['rules'].append(dict(id=id,title=title,text=text,theory=theory,pattern=pattern,examples=examples,comparison=comparison,mistakes=mistakes,limits=limits,mini=dict(prompt=mini,answer=answer,explanation=explanation),sources=sources or ['sag-verbs'],level='A'))

R('meaning','now',T('Действие сейчас','Дія зараз','An action now','En handling nu'),
 T('Presens — форма настоящего времени. Она помогает сказать, что человек делает или в каком состоянии находится. Контекст уточняет, происходит ли действие прямо сейчас.','Presens — форма теперішнього часу. Вона допомагає сказати, що людина робить або в якому стані перебуває. Контекст уточнює, чи дія відбувається саме зараз.','Presens is the present-tense form. It tells what someone does or what state they are in. Context shows whether the action is happening right now.','Presens är en verbform för nutid. Den visar vad någon gör eller hur något är. Sammanhanget visar om handlingen pågår just nu.'),
 T('В шведском нет обязательной отдельной формы для «делаю сейчас». Jag läser может значить «я читаю сейчас» или «я обычно читаю». Nu означает «сейчас» и делает первое значение яснее.','У шведській немає обов’язкової окремої форми для «роблю зараз». Jag läser може означати «я читаю зараз» або «я зазвичай читаю». Nu означає «зараз» і уточнює перше значення.','Swedish does not require a separate verb form for an action in progress. Jag läser can mean I am reading or I read regularly. Nu means now and makes the first meaning clearer.','Svenskan kräver ingen särskild verbform för en pågående handling. Jag läser kan gälla nu eller en vana. Nu gör det tydligt att handlingen sker just nu.'),
 S('subjekt → presens → nu'),[E('Jag läser en tidning nu.','Я сейчас читаю газету.','Я зараз читаю газету.','I am reading a newspaper now.'),E('Barnen leker ute.','Дети играют на улице.','Діти граються надворі.','The children are playing outside.')],
 T('Jag läser — действие; jag är trött — состояние. Оба предложения в presens.','Jag läser — дія; jag är trött — стан. Обидва речення в presens.','Jag läser is an action; jag är trött is a state. Both use presens.','Jag läser är en handling; jag är trött är ett tillstånd. Båda har presens.'),
 T('Не добавляй är перед läser: личная форма здесь уже есть.','Не додавай är перед läser: особова форма тут уже є.','Do not add är before läser: the finite verb is already there.','Lägg inte till är före läser: läser är redan ett finit verb.'),
 T('Форма не сообщает точное время сама по себе: слушай всю фразу.','Форма сама не повідомляє точний час: слухай усю фразу.','The form alone does not give an exact time; read the whole sentence.','Verbformen ensam ger ingen exakt tid; läs hela meningen.'),S('Nu / jag / lyssnar. → ?'),'Nu lyssnar jag.',T('После начального nu личный глагол стоит перед jag.','Після початкового nu особове дієслово стоїть перед jag.','After initial nu, the finite verb comes before jag.','Efter nu i början står det finita verbet före jag.'))

R('meaning','habits',T('Привычки и повторения','Звички й повторення','Habits and repetition','Vanor och upprepning'),
 T('Presens описывает и регулярные действия. Человек не обязан выполнять их в момент разговора. Varje dag означает «каждый день».','Presens описує й регулярні дії. Людина не мусить робити це в момент розмови. Varje dag означає «щодня».','Presens also describes regular actions. The person need not be doing them at the moment of speaking. Varje dag means every day.','Presens beskriver också vanor. Personen behöver inte göra det just när vi talar. Varje dag betyder alla dagar.'),
 T('Для привычки используй тот же глагол, что и для действия сейчас. Частоту уточняют ofta, ibland, alltid, aldrig. Не добавляй особое окончание из-за «обычно».','Для звички використовуй те саме дієслово, що й для дії зараз. Частоту уточнюють ofta, ibland, alltid, aldrig. Не додавай особливе закінчення через «зазвичай».','Use the same present form for habits and current actions. Ofta, ibland, alltid and aldrig specify frequency. A habit needs no extra verb ending.','Använd samma presensform för vanor och pågående handlingar. Ofta, ibland, alltid och aldrig anger hur ofta. Vanor får ingen egen verbändelse.'),
 S('subjekt → presens → ofta → … / varje dag'),[E('Vi promenerar varje dag.','Мы гуляем каждый день.','Ми гуляємо щодня.','We go for a walk every day.'),E('Hon cyklar ofta till skolan.','Она часто ездит в школу на велосипеде.','Вона часто їздить до школи велосипедом.','She often cycles to school.')],
 T('Nu — когда сейчас; varje dag — повторяющийся период; ofta — как часто.','Nu — коли зараз; varje dag — повторюваний період; ofta — як часто.','Nu locates an action now; varje dag gives a recurring period; ofta gives frequency.','Nu anger när, varje dag en återkommande tid och ofta hur ofta.'),
 T('Не меняй promenerar после vi: форма одинакова для всех лиц.','Не змінюй promenerar після vi: форма однакова для всіх осіб.','Do not change promenerar for vi: all persons share the form.','Ändra inte promenerar efter vi: formen är densamma för alla personer.'),
 T('Ofta не значит «всегда»: привычка допускает исключения.','Ofta не означає «завжди»: звичка допускає винятки.','Ofta does not mean always: there can be exceptions.','Ofta betyder inte alltid: undantag är möjliga.'),S('Varje dag = nu / every day?'),'every day',T('Выражение обозначает регулярность.','Вислів позначає регулярність.','The phrase signals repetition.','Uttrycket anger upprepning.'))

R('meaning','states',T('Факты и состояния','Факти й стани','Facts and states','Fakta och tillstånd'),
 T('Место жительства, имя, возраст, работа и устойчивые факты тоже выражаются через presens. Это не обязательно короткое действие.','Місце проживання, ім’я, вік, робота й сталі факти теж виражаються через presens. Це не обов’язково коротка дія.','Residence, name, age, work and lasting facts also use presens. They need not be brief actions.','Bostadsort, namn, ålder, arbete och bestående fakta uttrycks också med presens. Det behöver inte vara en kort handling.'),
 T('Выбирай глагол по смыслу: heter называет имя, bor сообщает о жилье, är описывает состояние или возраст, har — наличие. В шведском нужен глагол и там, где в русском или украинском его нет.','Обирай дієслово за змістом: heter називає ім’я, bor повідомляє про житло, är описує стан або вік, har — наявність. У шведській дієслово потрібне й там, де в українській його немає.','Choose by meaning: heter gives a name, bor gives residence, är expresses a state or age, and har expresses possession. Swedish requires a verb in these complete statements.','Välj verb efter betydelse: heter för namn, bor för bostad, är för tillstånd eller ålder och har för innehav. Dessa fullständiga påståenden behöver ett verb.'),S('heter / bor / är / har + …'),
 [E('Mina föräldrar bor i Uppsala.','Мои родители живут в Уппсале.','Мої батьки живуть в Уппсалі.','My parents live in Uppsala.'),E('Biblioteket är öppet idag.','Библиотека сегодня открыта.','Бібліотека сьогодні відкрита.','The library is open today.')],T('Jag är lärare — профессия; jag har en lärare — у меня есть преподаватель.','Jag är lärare — професія; jag har en lärare — у мене є викладач.','Jag är lärare means I am a teacher; jag har en lärare means I have a teacher.','Jag är lärare anger yrke; jag har en lärare anger att någon undervisar mig.'),T('Jag 30 år → Jag är 30 år.','Jag 30 år → Jag är 30 år.','Jag 30 år needs är: Jag är 30 år.','Jag 30 år behöver är: Jag är 30 år.'),T('Состояние может быть временным: idag не меняет форму är.','Стан може бути тимчасовим: idag не змінює форму är.','A state can be temporary: idag does not change är.','Ett tillstånd kan vara tillfälligt: idag ändrar inte är.'),S('Jag ___ en cykel. (ha)'),'har',T('Har сообщает, что велосипед у тебя есть.','Har повідомляє, що ти маєш велосипед.','Har expresses possession.','Har anger innehav.'))

R('meaning','future',T('Будущее по контексту','Майбутнє за контекстом','Future from context','Framtid genom sammanhanget'),
 T('Presens может говорить о будущем, если время понятно из контекста. I morgon / imorgon означает «завтра», nästa vecka — «на следующей неделе».','Presens може говорити про майбутнє, якщо час зрозумілий із контексту. I morgon / imorgon означає «завтра», nästa vecka — «наступного тижня».','Presens can refer to the future when the time is clear from context. I morgon / imorgon means tomorrow; nästa vecka means next week.','Presens kan uttrycka framtid när tiden framgår av sammanhanget. I morgon och imorgon betyder samma sak; nästa vecka är veckan efter denna.'),
 T('Форма глагола остаётся настоящей: börjar, kommer. Так часто говорят о расписании и договорённостях. Ska + инфинитив подчёркивает план или намерение, но не обязательно в каждом сообщении о будущем.','Форма дієслова лишається теперішньою: börjar, kommer. Так часто говорять про розклад і домовленості. Ska + інфінітив підкреслює план або намір, але не потрібне в кожному повідомленні про майбутнє.','The verb stays in presens: börjar, kommer. This is common for schedules and arrangements. Ska + infinitive can express a plan or intention, but is not required for every future reference.','Verbet står kvar i presens: börjar, kommer. Det är vanligt för tider och överenskommelser. Ska + infinitiv kan ange en plan eller avsikt men krävs inte varje gång vi talar om framtiden.'),S('i morgon → presens → subjekt → …'),
 [E('Kursen börjar nästa vecka.','Курс начинается на следующей неделе.','Курс починається наступного тижня.','The course starts next week.'),E('Imorgon kommer min syster.','Завтра приезжает моя сестра.','Завтра приїжджає моя сестра.','My sister is coming tomorrow.')],T('Jag arbetar idag и Jag arbetar imorgon: форма одна, время разное.','Jag arbetar idag і Jag arbetar imorgon: форма одна, час різний.','Jag arbetar idag and Jag arbetar imorgon use the same form for different times.','Jag arbetar idag och Jag arbetar imorgon har samma verbform men olika tid.'),T('После imorgon не сохраняй порядок jag kommer: Imorgon kommer jag.','Після imorgon не зберігай порядок jag kommer: Imorgon kommer jag.','After initial imorgon use Imorgon kommer jag.','Efter imorgon först: Imorgon kommer jag.'),T('Это не универсальная замена всех будущих конструкций: здесь нужны понятные планы или время.','Це не універсальна заміна всіх майбутніх конструкцій: тут потрібні зрозумілі плани або час.','This does not replace every future construction; use a clear time or arrangement here.','Det ersätter inte alla framtidsuttryck; här behövs en tydlig tid eller överenskommelse.'),S('I morgon ___ vi hemma. (vara)'),'är',T('Завтрашнее состояние выражается через är с указанием времени.','Завтрашній стан виражається через är із зазначенням часу.','Är can express tomorrow’s state with a time phrase.','Är kan ange morgondagens tillstånd med ett tidsuttryck.'))

R('forms','forms',T('Инфинитив, основа, личная форма','Інфінітив, основа, особова форма','Infinitive, stem, finite form','Infinitiv, stam, finit form'),
 T('Инфинитив называет действие: att arbeta, att läsa, att bo, att skriva. Att — отдельный показатель инфинитива, а не часть глагола. Личная форма presens позволяет построить сообщение: arbetar, läser, bor, skriver.','Інфінітив називає дію: att arbeta, att läsa, att bo, att skriva. Att — окремий показник інфінітива, а не частина дієслова. Особова форма presens дає змогу побудувати повідомлення: arbetar, läser, bor, skriver.','An infinitive names an action: att arbeta, att läsa, att bo, att skriva. Att is a separate infinitive marker, not part of the verb. Presens is finite and can form a statement: arbetar, läser, bor, skriver.','Infinitiven namnger en handling: att arbeta, att läsa, att bo, att skriva. Att är ett separat infinitivmärke. Presens är finit och kan bilda ett påstående: arbetar, läser, bor, skriver.'),
 T('Основа — часть, к которой добавляют окончание. В рабочей таблице: arbeta- + r, läs- + er, bo- + r, skriv- + er. Не всегда нужно отрезать a: у первой группы основа сохраняет a, а bo вовсе не оканчивается на a.','Основа — частина, до якої додають закінчення. У робочій таблиці: arbeta- + r, läs- + er, bo- + r, skriv- + er. Не завжди треба відрізати a: перша група зберігає a, а bo взагалі не закінчується на a.','A stem is the part that takes the ending. In our table: arbeta- + r, läs- + er, bo- + r, skriv- + er. Do not always remove a: group 1 retains it, and bo has no final a.','Stammen är delen som får en ändelse. I tabellen: arbeta- + r, läs- + er, bo- + r, skriv- + er. Ta inte alltid bort a: grupp 1 behåller a och bo saknar a.'),S('att + infinitiv ↔ stam + presensändelse'),[E('Jag arbetar på ett kontor.','Я работаю в офисе.','Я працюю в офісі.','I work in an office.'),E('Vi vill läsa tillsammans.','Мы хотим читать вместе.','Ми хочемо читати разом.','We want to read together.')],T('Arbeta называет действие; arbetar сообщает о нём; arbeta- — основа, совпадающая здесь с инфинитивом.','Arbeta називає дію; arbetar повідомляє про неї; arbeta- — основа, що тут збігається з інфінітивом.','Arbeta names the action; arbetar is finite; arbeta- is the stem, identical here to the infinitive.','Arbeta namnger handlingen; arbetar är finit; arbeta- är stammen, här lika med infinitiven.'),T('Не пиши Jag att arbeta или Jag arbeta в обычном утверждении.','Не пиши Jag att arbeta або Jag arbeta у звичайному твердженні.','Avoid Jag att arbeta and Jag arbeta in an ordinary statement.','Skriv inte Jag att arbeta eller Jag arbeta i ett vanligt påstående.'),T('Основа — помощь для знакомой группы, а не способ угадать все особые формы.','Основа — допомога для відомої групи, а не спосіб вгадати всі особливі форми.','A stem helps with a known group; it does not predict every irregular form.','Stammen hjälper när gruppen är känd; den förutsäger inte alla särskilda former.'),S('att skriva → ?'),'skriver',T('Skriv- + er → skriver.','Skriv- + er → skriver.','Skriv- + er gives skriver.','Skriv- + er blir skriver.'))

R('forms','persons',T('Одна форма для всех лиц','Одна форма для всіх осіб','One form for every person','Samma form för alla personer'),T('Jag arbetar, du arbetar, hon arbetar, vi arbetar, ni arbetar, de arbetar. Число и лицо подлежащего не меняют presens.','Jag arbetar, du arbetar, hon arbetar, vi arbetar, ni arbetar, de arbetar. Число й особа підмета не змінюють presens.','Jag arbetar, du arbetar, hon arbetar, vi arbetar, ni arbetar, de arbetar. Person and number do not change presens.','Jag arbetar, du arbetar, hon arbetar, vi arbetar, ni arbetar, de arbetar. Presens ändras inte efter person eller antal.'),T('Это верно и для особых форм: jag är, de är; du kan, vi kan. При замене имени местоимением сохраняй глагол: Sara läser → Hon läser. Подлежащее обычно нужно даже при одинаковой форме.','Це правильно й для особливих форм: jag är, de är; du kan, vi kan. Замінюючи ім’я займенником, зберігай дієслово: Sara läser → Hon läser. Підмет зазвичай потрібний навіть за однакової форми.','This also holds for special forms: jag är, de är; du kan, vi kan. Replacing a name with a pronoun keeps the verb: Sara läser → Hon läser. These sentences still need a subject.','Det gäller också särskilda former: jag är, de är; du kan, vi kan. Byt namn mot pronomen utan att ändra verbet: Sara läser → Hon läser. Meningarna behöver ändå subjekt.'),S('jag / du / han / hon / hen / vi / ni / de → arbetar'),[E('Jag bor nära skolan.','Я живу рядом со школой.','Я живу біля школи.','I live near the school.'),E('De bor nära skolan.','Они живут рядом со школой.','Вони живуть біля школи.','They live near the school.')],T('Bor не получает окончания множественного числа после de.','Bor не отримує закінчення множини після de.','Bor takes no plural ending after de.','Bor får ingen pluraländelse efter de.'),T('Не переноси окончания лиц из родного языка.','Не перенось особові закінчення з рідної мови.','Do not transfer person endings from another language.','Överför inte personändelser från ett annat språk.'),T('Одинаковая форма не означает свободный порядок слов.','Однакова форма не означає вільний порядок слів.','The shared form does not make word order free.','Samma form innebär inte fri ordföljd.'),S('Jag läser. → Vi …'),'Vi läser.',T('Меняется только подлежащее.','Змінюється лише підмет.','Only the subject changes.','Bara subjektet ändras.'))

R('forms','group1',T('Группа 1: -ar','Група 1: -ar','Group 1: -ar','Grupp 1: -ar'),T('У первой группы инфинитив оканчивается на -a, а presens — на -ar: arbeta → arbetar, prata → pratar, lyssna → lyssnar. К основе, оканчивающейся на a, добавляется r.','У першої групи інфінітив закінчується на -a, а presens — на -ar: arbeta → arbetar, prata → pratar, lyssna → lyssnar. До основи на a додаємо r.','Group 1 has an infinitive in -a and presens in -ar: arbeta → arbetar, prata → pratar, lyssna → lyssnar. Add r to the stem ending in a.','Grupp 1 har infinitiv på -a och presens på -ar: arbeta → arbetar, prata → pratar, lyssna → lyssnar. Lägg r till stammen som slutar på a.'),T('Разделение arbeta-r показывает основу. Для ученика удобно запоминать пару arbeta / arbetar. Эта группа большая, но одно наличие a в инфинитиве её не доказывает: läsa тоже имеет a.','Поділ arbeta-r показує основу. Зручно запам’ятовувати пару arbeta / arbetar. Ця група велика, але саме a в інфінітиві її не доводить: läsa також має a.','Arbeta-r shows the stem boundary. Learn arbeta / arbetar together. This is a large group, but final a alone does not identify it: läsa also ends in a.','Arbeta-r visar gränsen till ändelsen. Lär in arbeta / arbetar som ett par. Gruppen är stor, men a i infinitiven räcker inte för att identifiera den: läsa slutar också på a.'),S('arbeta- + r → arbetar'),[E('Han lagar soppa.','Он готовит суп.','Він готує суп.','He is making soup.'),E('Vi väntar på bussen.','Мы ждём автобус.','Ми чекаємо на автобус.','We are waiting for the bus.')],T('Arbeta → arbetar, но läsa → läser.','Arbeta → arbetar, але läsa → läser.','Arbeta → arbetar, but läsa → läser.','Arbeta → arbetar, men läsa → läser.'),T('Не превращай läsa в läsar по аналогии.','Не перетворюй läsa на läsar за аналогією.','Do not produce läsar by analogy with group 1.','Gör inte läsa till läsar efter mönstret i grupp 1.'),T('Группу проверяют по словарным формам; здесь тренируем только presens.','Групу перевіряють за словниковими формами; тут тренуємо лише presens.','Check a verb’s group using dictionary forms; only presens is practised here.','Kontrollera gruppen med ordbokens former; här tränas bara presens.'),S('lyssna → ?'),'lyssnar',T('Это глагол первой группы.','Це дієслово першої групи.','This verb belongs to group 1.','Verbet hör till grupp 1.'))

R('forms','group23',T('Группа 2: обычно -er','Група 2: зазвичай -er','Group 2: usually -er','Grupp 2: oftast -er'),T('В группе 2 у обычных примеров убирается конечное a и добавляется -er: läsa → läser, köpa → köper, ringa → ringer. Основа läs-, köp-, ring-.','У групі 2 у звичних прикладах прибираємо кінцеве a й додаємо -er: läsa → läser, köpa → köper, ringa → ringer. Основа läs-, köp-, ring-.','In common group 2 examples remove final a and add -er: läsa → läser, köpa → köper, ringa → ringer. The stems are läs-, köp-, ring-.','I vanliga exempel i grupp 2 tas a bort och -er läggs till: läsa → läser, köpa → köper, ringa → ringer. Stammarna är läs-, köp-, ring-.'),T('Подгруппы 2a и 2b различаются прежде всего другими формами, не presens; сейчас их заучивать не нужно. После основы на r встречается форма без добавочного er: lära → lär, köra → kör. Проверяй пару в словаре.','Підгрупи 2a і 2b різняться насамперед іншими формами, а не presens; зараз їх вивчати не потрібно. Після основи на r трапляється форма без додаткового er: lära → lär, köra → kör. Перевіряй пару в словнику.','Groups 2a and 2b mainly differ in other tenses, which are outside this lesson. A stem ending in r can have no added er: lära → lär, köra → kör. Check the dictionary pair.','Grupp 2a och 2b skiljer sig främst i andra former som inte tränas här. En stam på r kan sakna extra er: lära → lär, köra → kör. Kontrollera ordparet i ordboken.'),S('läs- + er → läser; lär- → lär'),[E('Du köper frukt.','Ты покупаешь фрукты.','Ти купуєш фрукти.','You buy fruit.'),E('Min granne kör buss.','Мой сосед водит автобус.','Мій сусід водить автобус.','My neighbour drives a bus.')],T('Köper и kör относятся к слабым глаголам группы 2, хотя длина окончания разная.','Köper і kör належать до слабких дієслів групи 2, хоча довжина закінчення різна.','Köper and kör are group 2 weak verbs although their endings look different.','Köper och kör hör till svaga verb i grupp 2 trots olika utseende.'),T('Не пиши köpar или körer.','Не пиши köpar або körer.','Avoid köpar and körer.','Skriv inte köpar eller körer.'),T('Не каждый -er означает группу 2: skriver — сильный глагол.','Не кожне -er означає групу 2: skriver — сильне дієслово.','Not every -er verb belongs to group 2: skriver is strong.','Alla verb på -er hör inte till grupp 2: skriver är starkt.'),S('ringa → ?'),'ringer',T('Ring- + er.','Ring- + er.','Ring- + er.','Ring- + er.'))

R('forms','group3',T('Группа 3: короткие глаголы на гласную','Група 3: короткі дієслова на голосну','Group 3: short vowel stems','Grupp 3: korta vokalstammar'),T('У типичных глаголов группы 3 инфинитив оканчивается на другую гласную, не a: bo, tro, må. В presens добавляется -r: bor, tror, mår.','У типових дієслів групи 3 інфінітив закінчується на іншу голосну, не a: bo, tro, må. У presens додаємо -r: bor, tror, mår.','Typical group 3 infinitives end in a vowel other than a: bo, tro, må. Add -r in presens: bor, tror, mår.','Typiska infinitiver i grupp 3 slutar på en annan vokal än a: bo, tro, må. Lägg till -r i presens: bor, tror, mår.'),T('Bo сообщает, где ты живёшь; tro — что ты думаешь или считаешь; må — как ты себя чувствуешь. Основа совпадает с инфинитивом. Но se и gå при похожем presens принадлежат к сильным/особым глаголам.','Bo повідомляє, де ти живеш; tro — що ти думаєш або вважаєш; må — як почуваєшся. Основа збігається з інфінітивом. Але se й gå за схожого presens належать до сильних/особливих дієслів.','Bo gives residence, tro means believe or think, and må concerns wellbeing. The stem matches the infinitive. Se and gå have similar-looking present forms but belong with strong or special verbs.','Bo anger bostad, tro vad du tror och må hur du mår. Stammen är lika med infinitiven. Se och gå har liknande presens men hör till starka eller särskilda verb.'),S('bo- + r → bor'),[E('Hur mår du idag?','Как ты себя сегодня чувствуешь?','Як ти сьогодні почуваєшся?','How are you feeling today?'),E('Jag tror det.','Я так думаю.','Я так думаю.','I think so.')],T('Bo → bor, но не boar; форма ser сама по себе не доказывает группу 3.','Bo → bor, але не boar; форма ser сама не доводить групу 3.','Bo → bor, never boar; ser alone does not prove membership in group 3.','Bo → bor, inte boar; ser i sig visar inte grupp 3.'),T('Не добавляй -ar после o в bo.','Не додавай -ar після o у bo.','Do not add -ar after the o in bo.','Lägg inte till -ar efter o i bo.'),T('Группы описывают всю систему форм; совпадение одного окончания недостаточно.','Групи описують усю систему форм; збігу одного закінчення недостатньо.','Groups describe the full set of forms; one matching ending is not enough.','Grupper gäller hela böjningen; en likadan ändelse räcker inte.'),S('tro → ?'),'tror',T('Добавляем r к tro.','Додаємо r до tro.','Add r to tro.','Lägg r till tro.'))

R('forms','group4',T('Группа 4: сильные глаголы','Група 4: сильні дієслова','Group 4: strong verbs','Grupp 4: starka verb'),T('Сильные глаголы меняют гласную в некоторых других формах. В presens часто бывает -er: skriva → skriver, dricka → dricker, komma → kommer. Это не делает их группой 2.','Сильні дієслова змінюють голосну в деяких інших формах. У presens часто є -er: skriva → skriver, dricka → dricker, komma → kommer. Це не робить їх групою 2.','Strong verbs change their vowel in some other forms. Presens often has -er: skriva → skriver, dricka → dricker, komma → kommer. That does not make them group 2.','Starka verb byter vokal i vissa andra former. Presens har ofta -er: skriva → skriver, dricka → dricker, komma → kommer. De hör ändå inte till grupp 2.'),T('К сильным относятся и короткие пары gå → går, se → ser, få → får. Учи точную пару инфинитив/presens. Подробные прошедшие формы оставим следующему уроку; в некоторых учебных таблицах особые неправильные глаголы стоят рядом с группой 4.','До сильних належать і короткі пари gå → går, se → ser, få → får. Учи точну пару інфінітив/presens. Докладні минулі форми залишимо наступному уроку; у деяких таблицях особливі неправильні дієслова стоять поруч із групою 4.','Strong verbs include short pairs such as gå → går, se → ser and få → får. Learn each infinitive/presens pair. Past forms come later; some teaching tables also place irregular verbs beside group 4.','Till starka verb hör också korta par som gå → går, se → ser och få → får. Lär in varje par infinitiv/presens. Dåtid kommer senare; vissa läromedel placerar även oregelbundna verb vid grupp 4.'),S('skriva → skriver; gå → går; se → ser'),[E('Vi skriver på svenska.','Мы пишем по-шведски.','Ми пишемо шведською.','We write in Swedish.'),E('Hon dricker vatten till maten.','Она пьёт воду во время еды.','Вона п’є воду під час їжі.','She drinks water with her meal.')],T('Läsa → läser и skriva → skriver похожи в presens, но относятся к разным группам.','Läsa → läser і skriva → skriver схожі в presens, але належать до різних груп.','Läsa → läser and skriva → skriver look similar in presens but belong to different groups.','Läsa → läser och skriva → skriver liknar varandra i presens men hör till olika grupper.'),T('Не создавай формы skrivar и gåer по общему шаблону.','Не утворюй skrivar і gåer за спільним шаблоном.','Do not invent skrivar or gåer using one universal pattern.','Skapa inte skrivar eller gåer med en enda generell regel.'),T('Термины «сильный» и «неправильный» не полностью взаимозаменяемы.','Терміни «сильний» і «неправильний» не повністю взаємозамінні.','Strong and irregular are not fully interchangeable terms.','Stark och oregelbunden betyder inte exakt samma sak.'),S('komma → ?'),'kommer',T('В паре сохраняются два m.','У парі зберігаються два m.','The pair retains double m.','Ordet behåller två m.'))

R('special','special',T('Är, har, går, gör, får, kommer, ser','Är, har, går, gör, får, kommer, ser','Är, har, går, gör, får, kommer, ser','Är, har, går, gör, får, kommer, ser'),T('Частые глаголы учи парами: vara → är, ha → har, gå → går, göra → gör, få → får, komma → kommer, se → ser. Не выводи är из окончания инфинитива.','Часті дієслова вчи парами: vara → är, ha → har, gå → går, göra → gör, få → får, komma → kommer, se → ser. Не виводь är із закінчення інфінітива.','Learn frequent verbs as pairs: vara → är, ha → har, gå → går, göra → gör, få → får, komma → kommer, se → ser. Är cannot be predicted from the infinitive ending.','Lär in vanliga verb i par: vara → är, ha → har, gå → går, göra → gör, få → får, komma → kommer, se → ser. Är kan inte bildas genom att bara byta en ändelse.'),T('Gå — идти пешком или ходить (также о занятиях: gå i skolan); komma — приходить/приезжать; göra — делать; se — видеть/смотреть. Få с предметом — получать, а får + инфинитив часто означает разрешение.','Gå — іти пішки або ходити (також про навчання: gå i skolan); komma — приходити/приїжджати; göra — робити; se — бачити/дивитися. Få з предметом — отримувати, а får + інфінітив часто означає дозвіл.','Gå can mean walk or attend (gå i skolan); komma means come; göra means do; se means see or watch. Få with an object means receive; får + infinitive often expresses permission.','Gå kan betyda förflytta sig till fots eller delta (gå i skolan); komma anger ankomst; göra en handling; se att uppfatta med ögonen. Få med objekt betyder ta emot; får + infinitiv anger ofta tillåtelse.'),S('vara → är; ha → har; göra → gör'),[E('Vad gör du på kvällen?','Что ты делаешь вечером?','Що ти робиш увечері?','What do you do in the evening?'),E('Jag får ett brev idag.','Я сегодня получаю письмо.','Я сьогодні отримую листа.','I am receiving a letter today.'),E('Du får sitta här.','Тебе можно сидеть здесь.','Тобі можна сидіти тут.','You may sit here.')],T('Jag är hemma — я дома; jag har ett hem — у меня есть дом.','Jag är hemma — я вдома; jag har ett hem — я маю дім.','Jag är hemma means I am at home; jag har ett hem means I have a home.','Jag är hemma anger plats; jag har ett hem anger innehav.'),T('Vara → är, а не varar в значении «быть»: varar относится к другому глаголу.','Vara → är, а не varar у значенні «бути»: varar належить іншому дієслову.','Vara meaning be has är, not varar; varar is a different verb.','Vara i betydelsen be har presens är; varar hör till ett annat verb.'),T('Проверяй значение в контексте: får не всегда означает обязанность.','Перевіряй значення в контексті: får не завжди означає обов’язок.','Read the context: får does not automatically mean obligation.','Läs sammanhanget: får betyder inte automatiskt skyldighet.'),S('Vi ___ en film. (se)'),'ser',T('Se → ser для всех лиц.','Se → ser для всіх осіб.','Se → ser for every person.','Se → ser för alla personer.'),['saol-forms'])

R('special','veta',T('Veta → vet: знать','Veta → vet: знати','Veta → vet: know','Veta → vet: veta'),T('Vet — особая форма presens без конечного r. Она означает знание факта или ответа. Одинаково: jag vet, hon vet, de vet.','Vet — особлива форма presens без кінцевого r. Вона означає знання факту або відповіді. Однаково: jag vet, hon vet, de vet.','Vet is a special present form with no final r. It means knowing a fact or an answer. Use jag vet, hon vet, de vet.','Vet är en särskild presensform utan r. Den anger kunskap om fakta eller svar. Formen är samma: jag vet, hon vet, de vet.'),T('Для навыка используют kan: Jag kan simma — я умею плавать. Для знакомого человека обычно känna: Jag känner Sara. В этой главе достаточно освоить vet svaret и vet inte.','Для вміння використовують kan: Jag kan simma — я вмію плавати. Для знайомої людини зазвичай känna: Jag känner Sara. Тут досить опанувати vet svaret і vet inte.','Use kan for an ability: Jag kan simma. Knowing a person normally takes känna: Jag känner Sara. Here focus on vet svaret and vet inte.','Använd kan för en färdighet: Jag kan simma. Om en bekant person används normalt känna: Jag känner Sara. Här tränar vi vet svaret och vet inte.'),S('veta → vet; subjekt → vet → inte'),[E('Vi vet svaret.','Мы знаем ответ.','Ми знаємо відповідь.','We know the answer.'),E('Jag vet inte.','Я не знаю.','Я не знаю.','I do not know.')],T('Vet — знать факт; kan — уметь или мочь.','Vet — знати факт; kan — уміти або могти.','Vet is knowing a fact; kan is ability or possibility.','Vet gäller fakta; kan gäller förmåga eller möjlighet.'),T('Не пиши veter или vetar.','Не пиши veter або vetar.','Do not write veter or vetar.','Skriv inte veter eller vetar.'),T('Не все шведские глаголы имеют r в presens.','Не всі шведські дієслова мають r у presens.','Not all Swedish present forms end in r.','Alla svenska presensformer slutar inte på r.'),S('Hon ___ inte svaret. (veta)'),'vet',T('После hon форма остаётся vet.','Після hon форма лишається vet.','Hon also takes vet.','Efter hon är formen också vet.'),['saol-forms'])

R('special','modals',T('Kan и vill + инфинитив','Kan і vill + інфінітив','Kan and vill + infinitive','Kan och vill + infinitiv'),T('Kunna → kan означает «мочь/уметь», vilja → vill — «хотеть». Личная форма модального глагола стоит первой, а следующий глагол — в инфинитиве без att.','Kunna → kan означає «могти/вміти», vilja → vill — «хотіти». Особова форма модального дієслова стоїть першою, а наступне дієслово — в інфінітиві без att.','Kunna → kan means can or be able to; vilja → vill means want to. The modal is finite; the next verb is an infinitive without att.','Kunna → kan anger förmåga eller möjlighet; vilja → vill anger en önskan. Hjälpverbet är finit och nästa verb står i infinitiv utan att.'),T('В Jag kan simma личная форма — kan, действие — simma. В Jag vill studera личная форма — vill, действие — studera. Не ставь два глагола в presens подряд. Инфинитив att studera в словаре не означает, что att нужно после vill.','У Jag kan simma особова форма — kan, дія — simma. У Jag vill studera особова форма — vill, дія — studera. Не став два дієслова в presens поспіль. Інфінітив att studera в словнику не означає, що att потрібне після vill.','In Jag kan simma, kan is finite and simma names the action. In Jag vill studera, vill is finite and studera is infinitive. Do not put both verbs in presens. Dictionary att studera does not require att after vill.','I Jag kan simma är kan finit och simma infinitiv. I Jag vill studera är vill finit och studera infinitiv. Sätt inte båda verben i presens. Ordbokens att studera innebär inte att att behövs efter vill.'),S('subjekt → kan / vill → infinitiv (utan att)'),[E('Jag kan simma.','Я умею плавать.','Я вмію плавати.','I can swim.'),E('Jag vill studera.','Я хочу учиться.','Я хочу навчатися.','I want to study.')],T('Jag studerar — я учусь; Jag vill studera — я хочу учиться, это не утверждение, что уже учусь.','Jag studerar — я навчаюся; Jag vill studera — я хочу навчатися, це не твердження, що вже навчаюся.','Jag studerar says I study; Jag vill studera expresses a wish, not a claim that I already study.','Jag studerar anger vad jag gör; Jag vill studera anger en önskan, inte att jag redan studerar.'),T('Jag kan simmar → Jag kan simma. Jag vill att studera → Jag vill studera.','Jag kan simmar → Jag kan simma. Jag vill att studera → Jag vill studera.','Jag kan simmar → Jag kan simma. Jag vill att studera → Jag vill studera.','Jag kan simmar → Jag kan simma. Jag vill att studera → Jag vill studera.'),T('Kan может означать возможность, а не только навык: Vi kan komma klockan två.','Kan може означати можливість, а не лише вміння: Vi kan komma klockan två.','Kan can mean possibility too: Vi kan komma klockan två.','Kan anger också möjlighet: Vi kan komma klockan två.'),S('De vill ___ svenska. (läsa)'),'läsa',T('После vill нужен инфинитив.','Після vill потрібен інфінітив.','Vill takes an infinitive.','Efter vill behövs infinitiv.'))

R('special','ska-maste',T('Ska и måste: план и необходимость','Ska і måste: план і необхідність','Ska and måste: plan and necessity','Ska och måste: plan och nödvändighet'),T('Skola → ska: план, намерение или договорённость. Словарный инфинитив skola в этом значении редко нужен в повседневной речи. Måste означает необходимость; учи его сразу в этой форме.','Skola → ska: план, намір або домовленість. Словниковий інфінітив skola в цьому значенні рідко потрібний у побутовому мовленні. Måste означає необхідність; учи його одразу в цій формі.','Skola → ska expresses a plan, intention or arrangement. The dictionary infinitive skola is rarely needed in everyday speech in this use. Måste expresses necessity; learn this form directly.','Skola → ska anger en plan, avsikt eller överenskommelse. Infinitiven skola behövs sällan i vardagligt tal i denna betydelse. Måste anger nödvändighet; lär in den formen direkt.'),T('После ska и måste нужен инфинитив без att: Jag ska arbeta. Jag måste gå. Måste не образуется добавлением r; не придумывай инфинитив måsta для этого урока. Это особый модальный глагол.','Після ska й måste потрібен інфінітив без att: Jag ska arbeta. Jag måste gå. Måste не утворюється додаванням r; не вигадуй інфінітив måsta для цього уроку. Це особливе модальне дієслово.','Ska and måste take an infinitive without att: Jag ska arbeta. Jag måste gå. Do not add r to måste or invent an infinitive måsta here; it is a special modal verb.','Ska och måste följs av infinitiv utan att: Jag ska arbeta. Jag måste gå. Lägg inte r till måste och skapa inte infinitiven måsta här; det är ett särskilt hjälpverb.'),S('subjekt → ska / måste → infinitiv'),[E('Jag ska arbeta.','Я собираюсь работать.','Я збираюся працювати.','I am going to work.'),E('Jag måste gå.','Мне нужно идти.','Мені треба йти.','I must go.')],T('Vill — желание; ska — план; måste — необходимость. Сам по себе план не означает желание.','Vill — бажання; ska — план; måste — необхідність. Сам план не означає бажання.','Vill expresses desire; ska a plan; måste necessity. A plan does not necessarily imply desire.','Vill anger önskan, ska plan och måste nödvändighet. En plan innebär inte alltid en önskan.'),T('Jag ska arbetar → Jag ska arbeta.','Jag ska arbetar → Jag ska arbeta.','Jag ska arbetar → Jag ska arbeta.','Jag ska arbetar → Jag ska arbeta.'),T('Для «запрещено» нужно får inte. Måste inte обычно означает отсутствие необходимости, а не запрет.','Для «заборонено» потрібне får inte. Måste inte зазвичай означає відсутність необхідності, а не заборону.','Use får inte for prohibition. Måste inte normally expresses lack of necessity rather than prohibition.','Använd får inte för förbud. Måste inte uttrycker normalt att något inte är nödvändigt, inte att det är förbjudet.'),S('Vi ___ gå nu: bussen kommer. (måste / vill)'),'måste',T('Ситуация подчёркивает необходимость успеть.','Ситуація підкреслює потребу встигнути.','The situation stresses needing to leave in time.','Situationen betonar att vi behöver hinna.'),['sag-verbs','saol-forms'])

R('sentences','negation',T('Отрицание: inte','Заперечення: inte','Negation: inte','Negation: inte'),T('В простом главном предложении с подлежащим в начале inte обычно стоит после личного глагола: Jag arbetar inte idag. Hon bor inte här. С модальным глаголом: Vi kan inte komma.','У простому головному реченні з підметом на початку inte зазвичай стоїть після особового дієслова: Jag arbetar inte idag. Hon bor inte här. З модальним дієсловом: Vi kan inte komma.','In a simple subject-first main clause, inte normally follows the finite verb: Jag arbetar inte idag. Hon bor inte här. With a modal: Vi kan inte komma.','I en enkel huvudsats med subjekt först står inte normalt efter det finita verbet: Jag arbetar inte idag. Hon bor inte här. Med hjälpverb: Vi kan inte komma.'),T('Если начинаешь со времени, подлежащее оказывается между личным глаголом и inte: Idag arbetar jag inte. В модальной конструкции inte не вытесняет инфинитив: Idag kan vi inte komma. Это схемы главного предложения.','Якщо починаєш із часу, підмет опиняється між особовим дієсловом та inte: Idag arbetar jag inte. У модальній конструкції inte не витісняє інфінітив: Idag kan vi inte komma. Це схеми головного речення.','With time first, the subject comes between the finite verb and inte: Idag arbetar jag inte. The infinitive remains after inte: Idag kan vi inte komma. These are main-clause patterns.','Med tid först står subjektet mellan det finita verbet och inte: Idag arbetar jag inte. Infinitiven står kvar efter inte: Idag kan vi inte komma. Mönstren gäller huvudsatser.'),S('S → V1 → inte → (V2 infinitiv) → …'),[E('Hon bor inte här.','Она не живёт здесь.','Вона не живе тут.','She does not live here.'),E('Vi kan inte komma.','Мы не можем прийти.','Ми не можемо прийти.','We cannot come.')],T('Kan komma — можем прийти; kan inte komma — не можем прийти.','Kan komma — можемо прийти; kan inte komma — не можемо прийти.','Kan komma means can come; kan inte komma means cannot come.','Kan komma anger möjlighet; kan inte komma nekar möjligheten.'),T('Vi inte kan komma → Vi kan inte komma.','Vi inte kan komma → Vi kan inte komma.','Vi inte kan komma → Vi kan inte komma.','Vi inte kan komma → Vi kan inte komma.'),T('В придаточных порядок другой; они не входят в этот урок. Не обобщай эту схему на все предложения языка.','У підрядних порядок інший; вони не входять до цього уроку. Не узагальнюй схему на всі речення мови.','Subordinate clauses have a different pattern and are outside this lesson. Do not apply this to every clause in Swedish.','Bisatser har ett annat mönster och ingår inte här. Använd inte detta som regel för alla svenska satser.'),S('Hon / kan / komma / inte. → ?'),'Hon kan inte komma.',T('Inte стоит после kan и до komma.','Inte стоїть після kan і перед komma.','Inte comes after kan and before komma.','Inte står efter kan och före komma.'),['sag-order'])

R('sentences','v2',T('V2: глагол на второй позиции','V2: дієслово на другій позиції','V2: verb in second position','V2: verbet på andra plats'),T('В обычном утвердительном главном предложении личный глагол занимает вторую позицию. Позиция — это часть предложения, а не отдельное слово. På morgonen целиком занимает первую позицию.','У звичайному розповідному головному реченні особове дієслово займає другу позицію. Позиція — це член речення, а не окреме слово. På morgonen цілком займає першу позицію.','In an ordinary declarative main clause the finite verb has position two. A position is a constituent, not one word. På morgonen occupies the whole first position.','I en vanlig påståendehuvudsats står det finita verbet på andra plats. En plats är en satsdel, inte ett ord. Hela på morgonen tar första platsen.'),T('Jag arbetar idag → Idag arbetar jag. После начального времени подлежащее перемещается за глагол. Если глаголов два, вторую позицию занимает только личный: Imorgon ska jag arbeta.','Jag arbetar idag → Idag arbetar jag. Після початкового часу підмет переходить за дієслово. Якщо дієслів два, другу позицію займає лише особове: Imorgon ska jag arbeta.','Jag arbetar idag → Idag arbetar jag. After initial time, put the subject after the verb. With two verbs only the finite one takes position two: Imorgon ska jag arbeta.','Jag arbetar idag → Idag arbetar jag. Efter tid först kommer subjektet efter verbet. Med två verb tar bara det finita verbet andra platsen: Imorgon ska jag arbeta.'),S('[1 tid / subjekt] → [2 finit verb] → [subjekt om inte först] → …'),[E('Jag arbetar idag.','Я сегодня работаю.','Я сьогодні працюю.','I am working today.'),E('Idag arbetar jag.','Сегодня я работаю.','Сьогодні я працюю.','Today I am working.')],T('На первом месте можно выделить время; смысл действия сохраняется.','На першому місці можна виділити час; зміст дії зберігається.','Putting time first changes emphasis but keeps the action.','Tid först ändrar betoning men behåller handlingen.'),T('Idag jag arbetar → Idag arbetar jag.','Idag jag arbetar → Idag arbetar jag.','Idag jag arbetar → Idag arbetar jag.','Idag jag arbetar → Idag arbetar jag.'),T('V2 — не правило «второе слово» и не схема вопроса да/нет.','V2 — не правило «друге слово» й не схема питання так/ні.','V2 does not mean second word and is not the yes/no question pattern.','V2 betyder inte andra ordet och är inte mönstret för ja/nej-frågor.'),S('På kvällen / vi / läser. → ?'),'På kvällen läser vi.',T('På kvällen — одна часть, затем läser и vi.','På kvällen — одна частина, потім läser і vi.','På kvällen is one constituent, followed by läser and vi.','På kvällen är en satsdel, sedan kommer läser och vi.'),['sag-order'])

R('sentences','questions',T('Два типа вопросов','Два типи запитань','Two kinds of question','Två typer av frågor'),T('Вопрос да/нет начинается с личного глагола: Arbetar du idag? Для вопроса с вопросительным словом поставь его перед личным глаголом: Var arbetar du?','Питання так/ні починається з особового дієслова: Arbetar du idag? Для питання з питальним словом постав його перед особовим дієсловом: Var arbetar du?','A yes/no question starts with the finite verb: Arbetar du idag? For a question with a question word put it before the finite verb: Var arbetar du?','En ja/nej-fråga börjar med det finita verbet: Arbetar du idag? Med frågeord står det före det finita verbet: Var arbetar du?'),T('Var — где, vad — что, när — когда, hur — как. С модальным глаголом спрашивай Kan du simma? / När ska du arbeta? Инфинитив остаётся после подлежащего. Здесь строим вопросы, где вопросительное слово не является подлежащим.','Var — де, vad — що, när — коли, hur — як. З модальним дієсловом: Kan du simma? / När ska du arbeta? Інфінітив лишається після підмета. Тут будуємо питання, де питальне слово не є підметом.','Var means where, vad what, när when, hur how. With modals use Kan du simma? / När ska du arbeta? The infinitive remains after the subject. Here the question word is not itself the subject.','Var frågar om plats, vad om sak eller handling, när om tid och hur om sätt. Med hjälpverb: Kan du simma? / När ska du arbeta? Infinitiven står efter subjektet. Här är frågeordet inte självt subjekt.'),S('V1 → S → …? / frågeord → V1 → S → …?'),[E('Arbetar du idag?','Ты сегодня работаешь?','Ти сьогодні працюєш?','Are you working today?'),E('Var arbetar du?','Где ты работаешь?','Де ти працюєш?','Where do you work?')],T('Du arbetar idag. — сообщение; Arbetar du idag? — вопрос с ответом да/нет.','Du arbetar idag. — повідомлення; Arbetar du idag? — питання з відповіддю так/ні.','Du arbetar idag is a statement; Arbetar du idag asks for yes or no.','Du arbetar idag är ett påstående; Arbetar du idag är en ja/nej-fråga.'),T('Var du arbetar? → Var arbetar du?','Var du arbetar? → Var arbetar du?','Var du arbetar? → Var arbetar du?','Var du arbetar? → Var arbetar du?'),T('Не добавляй английское do. Вопрос с vem как подлежащим устроен иначе и здесь не тренируется.','Не додавай англійське do. Питання з vem як підметом має іншу будову й тут не тренується.','Do not add English do. A question with vem as subject has a different structure and is outside this practice.','Lägg inte till engelskans do. Frågor där vem är subjekt har ett annat mönster och tränas inte här.'),S('Du bor i Lund. → Var …?'),'Var bor du?',T('Var → bor → du.','Var → bor → du.','Var → bor → du.','Var → bor → du.'),['sag-order'])

R('sentences','adverbs',T('Когда и как часто','Коли й як часто','When and how often','När och hur ofta'),T('Nu, idag, varje dag, på morgonen, på kvällen — обстоятельства времени. Ofta, ibland, alltid, aldrig выражают частоту. Они отвечают на разные вопросы, хотя обе категории помогают говорить о распорядке.','Nu, idag, varje dag, på morgonen, på kvällen — обставини часу. Ofta, ibland, alltid, aldrig виражають частоту. Вони відповідають на різні питання, хоча обидві категорії допомагають говорити про розпорядок.','Nu, idag, varje dag, på morgonen and på kvällen locate an action in time. Ofta, ibland, alltid and aldrig express frequency. These are different questions, although both help describe routines.','Nu, idag, varje dag, på morgonen och på kvällen anger tid. Ofta, ibland, alltid och aldrig anger frekvens. De svarar på olika frågor men hjälper alla att beskriva vanor.'),T('Время удобно поставить в конце или начале с V2: Jag läser på kvällen / På kvällen läser jag. Нейтральное место частотного наречия после личного глагола и подлежащего: Jag läser ofta / Idag läser jag ofta. С модальным: Jag kan ofta komma.','Час зручно ставити в кінці або на початку з V2: Jag läser på kvällen / På kvällen läser jag. Нейтральне місце частотного прислівника після особового дієслова й підмета: Jag läser ofta / Idag läser jag ofta. З модальним: Jag kan ofta komma.','Time can go at the end or first with V2: Jag läser på kvällen / På kvällen läser jag. A neutral frequency position follows the finite verb and subject: Jag läser ofta / Idag läser jag ofta. With a modal: Jag kan ofta komma.','Tid kan stå sist eller först med V2: Jag läser på kvällen / På kvällen läser jag. Frekvens står neutralt efter finit verb och subjekt: Jag läser ofta / Idag läser jag ofta. Med hjälpverb: Jag kan ofta komma.'),S('S → V1 → ofta / alltid / aldrig → (infinitiv) → … → tid'),[E('Jag läser ofta på kvällen.','Я часто читаю вечером.','Я часто читаю ввечері.','I often read in the evening.'),E('Hon dricker aldrig kaffe.','Она никогда не пьёт кофе.','Вона ніколи не п’є кави.','She never drinks coffee.')],T('Ibland может стоять и первым: Ibland läser jag. Тогда соблюдай V2.','Ibland може стояти й першим: Ibland läser jag. Тоді дотримуйся V2.','Ibland can also go first: Ibland läser jag. Keep V2.','Ibland kan också stå först: Ibland läser jag. Behåll V2.'),T('Aldrig уже выражает отрицание: в обычной фразе не добавляй inte.','Aldrig уже виражає заперечення: у звичайній фразі не додавай inte.','Aldrig already negates: do not add inte in an ordinary sentence.','Aldrig nekar redan: lägg inte till inte i en vanlig mening.'),T('Это удобные нейтральные места, а не запрет иных порядков для особого акцента. Idag и i dag — оба правильные написания.','Це зручні нейтральні місця, а не заборона інших порядків для особливого наголосу. Idag та i dag — обидва правильні написання.','These are useful neutral positions, not a ban on other positions for emphasis. Idag and i dag are both correct spellings.','Detta är neutrala placeringar, inte ett förbud mot andra placeringar för betoning. Idag och i dag är båda korrekta.'),S('Ibland / jag / lagar / soppa. → ?'),'Ibland lagar jag soppa.',T('После начального ibland следует глагол.','Після початкового ibland іде дієслово.','Initial ibland is followed by the finite verb.','Efter ibland först kommer det finita verbet.'),['sag-order','isof-time'])

R('reference','errors',T('Проверь четыре вещи','Перевір чотири речі','Check four things','Kontrollera fyra saker'),T('Перед отправкой текста найди подлежащее и личный глагол. Затем проверь его словарную форму, место inte и инфинитив после модального глагола. Читай целое предложение вслух.','Перед надсиланням тексту знайди підмет і особове дієслово. Потім перевір словникову форму, місце inte та інфінітив після модального дієслова. Прочитай ціле речення вголос.','Before sharing a text, find the subject and finite verb. Check the dictionary form, position of inte and infinitive after a modal. Read the whole sentence aloud.','Hitta subjektet och det finita verbet innan du lämnar texten. Kontrollera ordboksformen, platsen för inte och infinitiv efter hjälpverb. Läs hela meningen högt.'),T('Порядок проверки: 1) форма bor, не boar; 2) Idag arbetar jag, не Idag jag arbetar; 3) Jag arbetar inte, не Jag inte arbetar; 4) Jag vill läsa, не Jag vill läser. Шпаргалка ниже объединяет эти решения.','Порядок перевірки: 1) форма bor, не boar; 2) Idag arbetar jag, не Idag jag arbetar; 3) Jag arbetar inte, не Jag inte arbetar; 4) Jag vill läsa, не Jag vill läser. Шпаргалка нижче об’єднує ці рішення.','Check in order: 1) bor, not boar; 2) Idag arbetar jag; 3) Jag arbetar inte; 4) Jag vill läsa. The reference tables below bring these decisions together.','Kontrollera i ordning: 1) bor, inte boar; 2) Idag arbetar jag; 3) Jag arbetar inte; 4) Jag vill läsa. Snabbtabellerna nedan samlar dessa val.'),S('form → V2 → inte → infinitiv'),[E('Imorgon vill vi köpa mat.','Завтра мы хотим купить продукты.','Завтра ми хочемо купити продукти.','Tomorrow we want to buy food.'),E('På morgonen dricker jag inte kaffe.','Утром я не пью кофе.','Уранці я не п’ю кави.','In the morning I do not drink coffee.')],T('Оценивай по одному решению: правильный инфинитив не исправляет ошибку V2.','Оцінюй по одному рішенню: правильний інфінітив не виправляє помилку V2.','Check each decision: a correct infinitive does not fix incorrect V2.','Kontrollera varje val: rätt infinitiv rättar inte ett V2-fel.'),T('Hon är läser → Hon läser. Äр не является универсальным помощником для действия.','Hon är läser → Hon läser. Är не є універсальним допоміжним дієсловом для дії.','Hon är läser → Hon läser. Är is not a general auxiliary for ongoing actions.','Hon är läser → Hon läser. Är är inget allmänt hjälpverb för pågående handlingar.'),T('Самопроверка помогает найти ошибки, но не заменяет обратную связь преподавателя.','Самоперевірка допомагає знайти помилки, але не замінює відгук викладача.','Self-review helps find errors but does not replace teacher feedback.','Egen kontroll hjälper men ersätter inte lärarens återkoppling.'),S('Rätta: Imorgon vi ska läser.'),'Imorgon ska vi läsa.',T('Ska на второй позиции, läsa — инфинитив.','Ska на другій позиції, läsa — інфінітив.','Ska is in position two and läsa is infinitive.','Ska står på andra plats och läsa är infinitiv.'),['sag-order','sag-verbs'])

