import re
terms={'subjekt':T('подлежащее','підмет','subject','subjekt'),'presens':S('presens'),'tid':T('время','час','time','tid'),'finit':T('личный','особове','finite','finit'),'verb':T('глагол','дієслово','verb','verb'),'infinitiv':T('инфинитив','інфінітив','infinitive','infinitiv'),'stam':T('основа','основа','stem','stam'),'presensändelse':T('окончание presens','закінчення presens','presens ending','presensändelse'),'frågeord':T('вопросительное слово','питальне слово','question word','frågeord'),'utan att':T('без att','без att','without att','utan att'),'om inte först':T('если не в начале','якщо не на початку','if not first','om inte först'),'form':T('форма','форма','form','form')}
for r in [r for s in v['sections'] for r in s['rules']]:
 source=r['pattern']['sv'].replace('V2 infinitiv','infinitiv')
 for lang in LANGS:
  pattern=source
  for term in sorted(terms,key=len,reverse=True):pattern=re.sub(r'\b'+re.escape(term)+r'\b',lambda m:terms[term][lang],pattern)
  r['pattern'][lang]=pattern
glosses={'vara':'vara','ha':'äga eller ha tillgång till','gå':'förflytta sig till fots','göra':'utföra en handling','få':'ta emot; ha tillåtelse','komma':'anlända','se':'uppfatta med ögonen','veta':'ha kunskap om fakta','vilja':'önska','kunna':'ha förmåga eller möjlighet','skola':'ha en plan eller avsikt','—':'behöva; nödvändighet'}
for row,(inf,present,ru,uk,en) in zip(next(t for t in v['tables'] if t['id']=='special-verbs')['rows'],verbs):
 row['cells'][2]['sv']=glosses[inf]
for inf,present,ru,uk,en in verbs:
 if not any(w['present']==present for w in v['cheatSheet']):
  v['cheatSheet'].append(dict(inf=inf,present=present,meaning=T(ru,uk,en,glosses[inf])))
